const logBox = document.getElementById("log");

function appendLog(text) {
  logBox.textContent += text.toString() + "\n"; // 追加原始数据
  logBox.scrollTop = logBox.scrollHeight; // 自动置底
}
{
  const child = spawn("tail", ["-f", "/data/adb/v2fly/v2ray.log"]);

  child.stdout.on("data", (data) => appendLog(data.toString()));
  child.stderr.on("data", (data) => appendLog(data.toString()));

  child.on("close", (code) => {
    appendLog(`\n[系统] 进程已退出，退出码: ${code}\n`);
  });
}
